# Course normal scores. Draw iid observations from the selected population,
# ranks their absolute values, then restores their signs before summing.
normal_scores <- function(n) qnorm((n + 1 + seq_len(n)) / (2 * n + 2))

chisq_median <- qchisq(0.5, df = 3)
population_labels <- c(normal = "正态 N(0,1)", cauchy = "柯西 C(0,1)",
                       chisq = "卡方 χ²(3)（已减去理论中位数）")

draw_population <- function(size, population = "normal") {
  switch(population,
         normal = rnorm(size),
         cauchy = rcauchy(size, location = 0, scale = 1),
         chisq = rchisq(size, df = 3) - chisq_median,
         stop("Unknown population: ", population))
}

population_density <- function(x, population = "normal") {
  switch(population,
         normal = dnorm(x),
         cauchy = dcauchy(x, location = 0, scale = 1),
         chisq = dchisq(x + chisq_median, df = 3),
         stop("Unknown population: ", population))
}

normal_score_statistic <- function(x) {
  x <- x[x != 0]
  n <- length(x)
  if (!n) stop("All differences are zero")
  r <- rank(abs(x), ties.method = "average")
  s <- qnorm((n + 1 + r) / (2 * n + 2)) * sign(x)
  sum(s) / sqrt(sum(s^2))
}

simulate_experiment <- function(n, B = 10000L, seed = 20261005L, population = "normal") {
  stopifnot(length(n) == 1L, n == floor(n), n >= 3, n <= 200, B >= 1)
  stopifnot(length(population) == 1L, population %in% names(population_labels))
  old_kind <- RNGkind()
  had_seed <- exists(".Random.seed", .GlobalEnv, inherits = FALSE)
  if (had_seed) old_seed <- get(".Random.seed", .GlobalEnv)
  on.exit({
    do.call(RNGkind, as.list(old_kind))
    if (had_seed) assign(".Random.seed", old_seed, .GlobalEnv)
    else if (exists(".Random.seed", .GlobalEnv, inherits = FALSE))
      rm(".Random.seed", envir = .GlobalEnv)
  }, add = TRUE)
  RNGkind("Mersenne-Twister", "Inversion", "Rejection")
  set.seed(as.integer((as.double(seed) + 1009 * n) %% 2147483647))
  a <- normal_scores(n)
  samples <- matrix(draw_population(n * B, population), nrow = n, ncol = B)
  denominator <- sqrt(sum(a^2))
  statistics <- vapply(seq_len(B), function(b) {
    x <- samples[, b]
    # Continuous draws have distinct absolute values with probability one.
    # Use the general formula in the exceptional zero/tie case.
    if (any(x == 0) || anyDuplicated(abs(x))) normal_score_statistic(x)
    else sum(a * sign(x)[order(abs(x))]) / denominator
  }, numeric(1))
  x <- samples[, 1]
  r <- rank(abs(x), ties.method = "average")
  sample <- data.frame(x = x, r = r,
                       score = qnorm((n + 1 + r) / (2 * n + 2)) * sign(x),
                       sign = factor(ifelse(x > 0, "正差值", "负差值"),
                                     levels = c("正差值", "负差值")))
  list(statistics = statistics, sample = sample[order(sample$r), ], n = n, B = B,
       population = population)
}

simulate_normal_score <- function(n, B = 10000L, seed = 20261005L, population = "normal") {
  simulate_experiment(n, B, seed, population)$statistics
}

# Sign test: continuous median-zero null implies P(X > 0) = 1/2,
# including asymmetric populations. Exact two-sided tails at p0=1/2.
sign_pvalues <- function(S, n, method = "exact") {
  stopifnot(method %in% c("exact", "normal"), n > 0,
            all(S >= 0 & S <= n & S == floor(S)))
  if (method == "exact")
    pmin(1, 2*pbinom(pmin(S, n-S), size = n, prob = 0.5))
  else 2*pnorm(-pmax(abs(S-n/2)-0.5, 0)/sqrt(n/4))
}

sign_components <- function(x, M0 = 0) {
  stopifnot(all(is.finite(x)), length(M0) == 1L, is.finite(M0))
  differences <- x-M0
  differences <- differences[differences != 0]
  n <- length(differences)
  stopifnot(n > 0)
  S <- sum(differences > 0)
  list(S = S, n = n, Z = (S-n/2)/sqrt(n/4),
       p_exact = sign_pvalues(S, n, "exact"),
       p_normal = sign_pvalues(S, n, "normal"))
}

simulate_sign_experiment <- function(n, population = "normal",
                                     B = 5000L, seed = 20261007L) {
  stopifnot(length(n) == 1L, n == floor(n), n >= 3, n <= 200,
            population %in% names(population_labels), B >= 1)
  old_kind <- RNGkind()
  had_seed <- exists(".Random.seed", .GlobalEnv, inherits = FALSE)
  if (had_seed) old_seed <- get(".Random.seed", .GlobalEnv)
  on.exit({
    do.call(RNGkind, as.list(old_kind))
    if (had_seed) assign(".Random.seed", old_seed, .GlobalEnv)
    else if (exists(".Random.seed", .GlobalEnv, inherits = FALSE))
      rm(".Random.seed", envir = .GlobalEnv)
  }, add = TRUE)
  RNGkind("Mersenne-Twister", "Inversion", "Rejection")
  set.seed(as.integer((as.double(seed) + 1019*n) %% 2147483647))
  x <- matrix(draw_population(n*B, population), nrow = n)
  # These continuous generators have no atom at the hypothesized median.
  stopifnot(!any(x == 0))
  S <- colSums(x > 0)
  list(statistics = (S-n/2)/sqrt(n/4), S = S,
       p_exact = sign_pvalues(S, n, "exact"),
       p_normal = sign_pvalues(S, n, "normal"),
       sample = x[, 1], details = sign_components(x[, 1]),
       n = n, B = B, population = population)
}

# Two-sided one-sample KS: include both sides of every ECDF jump.
ks_components <- function(x, cdf = pnorm) {
  x <- sort(x)
  n <- length(x)
  stopifnot(n > 0, all(is.finite(x)))
  f <- cdf(x)
  after <- seq_len(n) / n
  before <- (seq_len(n) - 1) / n
  plus <- after - f
  minus <- f - before
  use_plus <- max(plus) >= max(minus)
  j <- if (use_plus) which.max(plus) else which.max(minus)
  list(D = max(plus, minus), x = x[j], theoretical = f[j],
       empirical = if (use_plus) after[j] else before[j],
       left_limit = !use_plus, sample = x)
}

# Kolmogorov limit law. Theta transformation prevents cancellation near zero.
kolmogorov_cdf <- function(z) {
  vapply(z, function(t) {
    if (is.na(t)) return(NA_real_)
    if (t <= 0) return(0)
    if (is.infinite(t)) return(1)
    if (t < 1) {
      k <- seq_len(20L)
      value <- sqrt(2 * pi) / t * sum(exp(-(2*k - 1)^2 * pi^2 / (8*t^2)))
    } else {
      k <- seq_len(50L)
      value <- 1 - 2 * sum((-1)^(k - 1) * exp(-2*k^2*t^2))
    }
    max(0, min(1, value))
  }, numeric(1))
}

kolmogorov_density <- function(z) {
  vapply(z, function(t) {
    if (is.na(t)) return(NA_real_)
    if (t <= 0 || is.infinite(t)) return(0)
    if (t < 1) {
      a <- (2*seq_len(20L) - 1)^2 * pi^2 / 8
      value <- sqrt(2*pi) * sum(exp(-a/t^2) * (2*a/t^4 - 1/t^2))
    } else {
      k <- seq_len(50L)
      value <- 8*t * sum((-1)^(k - 1) * k^2 * exp(-2*k^2*t^2))
    }
    max(0, value)
  }, numeric(1))
}

simulate_ks_experiment <- function(n, B = 5000L, seed = 20261006L) {
  stopifnot(length(n) == 1L, n == floor(n), n >= 3, n <= 500, B >= 1)
  old_kind <- RNGkind()
  had_seed <- exists(".Random.seed", .GlobalEnv, inherits = FALSE)
  if (had_seed) old_seed <- get(".Random.seed", .GlobalEnv)
  on.exit({
    do.call(RNGkind, as.list(old_kind))
    if (had_seed) assign(".Random.seed", old_seed, .GlobalEnv)
    else if (exists(".Random.seed", .GlobalEnv, inherits = FALSE))
      rm(".Random.seed", envir = .GlobalEnv)
  }, add = TRUE)
  RNGkind("Mersenne-Twister", "Inversion", "Rejection")
  # A common sequence shows how one ECDF changes when observations are added.
  set.seed(seed)
  sample <- rnorm(500L)[seq_len(n)]
  details <- ks_components(sample)
  set.seed(as.integer((as.double(seed) + 1013*n) %% 2147483647))
  samples <- matrix(rnorm(n*B), nrow = n)
  upper <- seq_len(n) / n
  lower <- (seq_len(n) - 1) / n
  d <- vapply(seq_len(B), function(b) {
    u <- pnorm(sort(samples[, b]))
    max(upper - u, u - lower)
  }, numeric(1))
  list(statistics = sqrt(n)*d, D = d, sample = sample, details = details,
       n = n, B = B, p_asymptotic = 1 - kolmogorov_cdf(sqrt(n)*details$D))
}

// Report visible SVG containers so plots are redrawn at their actual width.
(function () {
  function attach() {
    document.querySelectorAll('.svg-plot').forEach(function (element) {
      if (element.dataset.observed) return;
      element.dataset.observed = 'true';
      var timer;
      var observer = new ResizeObserver(function () {
        clearTimeout(timer);
        timer = setTimeout(function () {
          var width = Math.round(element.getBoundingClientRect().width);
          if (width > 0 && window.Shiny && Shiny.setInputValue) {
            Shiny.setInputValue(element.dataset.plot + '_width', width);
          }
        }, 150);
      });
      observer.observe(element);
    });
  }
  document.addEventListener('DOMContentLoaded', attach);
  document.addEventListener('shiny:connected', attach);
})();

body { background: #fafbfc; color: #263d4b; font-family: 'Microsoft YaHei', 'PingFang SC', sans-serif; }
.demo { max-width: 1280px; margin: 25px auto; padding: 0 25px; }
h1 { font-size: 27px; font-weight: 600; margin: 0 0 18px; }
.frame { display: grid; grid-template-columns: minmax(0, 1fr) 350px; background: white; border: 1px solid #dce4e9; border-radius: 8px; padding: 18px 24px 12px; }
.figure { min-width: 0; }
.population-controls { grid-column: 1 / -1; border-bottom: 1px solid #edf0f3; margin-bottom: 14px; padding-bottom: 6px; }
.population-controls .shiny-input-container { width: 100%; margin: 0; }
.population-controls .control-label { font-size: 13px; font-weight: 400; margin-bottom: 8px; }
.population-controls .radio-inline { margin: 0 24px 6px 0; color: #465b6b; font-size: 13px; }
.comparison-note { grid-column: 1 / -1; font-size: 11px; color: #8795a0; margin: 8px 0 0; }
.figure-heading { display: flex; justify-content: space-between; align-items: center; padding: 0 18px 8px; }
.figure-heading .shiny-text-output { font-size: 21px; font-weight: 600; }
.figure-heading > span:last-child { color: #8795a0; font-size: 12px; }
.legend { display: flex; justify-content: center; gap: 28px; color: #687b88; font-size: 12px; }
.legend span::before { content: ''; display: inline-block; width: 22px; vertical-align: middle; margin-right: 7px; }
.legend-hist::before { height: 10px; background: #638fa9; }
.legend-normal::before { height: 3px; background: #d9863b; }
.formulas { align-self: center; border-left: 1px solid #e7ecf0; padding: 5px 0 5px 24px; text-align: center; }
.assumption { color: #5e7180; font-size: 14px; margin: 0 0 16px; }
.skew-note { color: #a3612f; }
.limit-condition { color: #8795a0; font-size: 11px; margin: 12px 0 -8px; }
math { font-family: 'Cambria Math', 'Times New Roman', serif; font-size: 20px; margin: 16px 0; }
.rank-note { color: #8795a0; font-size: 12px; margin: 16px 0 0; }
.controls { grid-column: 1 / -1; display: flex; align-items: center; gap: 14px; border-top: 1px solid #edf0f3; margin-top: 14px; padding-top: 10px; }
.controls .shiny-input-container { flex: 1; width: auto !important; margin: 0 28px 0 10px; }
.controls .control-label { font-weight: 400; font-size: 13px; }
.controls .btn { background: white; border: 1px solid #cfdce5; border-radius: 5px; padding: 8px 22px; color: #36586d; }
.controls #play { color: white; background: #527e98; border-color: #527e98; }
.controls #ks_play { color: white; background: #527e98; border-color: #527e98; }
.controls #sign_play { color: white; background: #527e98; border-color: #527e98; }
.demo .nav-tabs { border-bottom-color: #dce4e9; margin-bottom: 22px; }
.demo .nav-tabs > li > a { color: #627888; border-radius: 5px 5px 0 0; }
.demo .nav-tabs > li.active > a { color: #36586d; font-weight: 600; background: #fff; }
.svg-plot, .svg-plot .shiny-html-output { width: 100%; height: 100%; min-width: 0; }
.svg-plot svg { display: block; width: 100%; height: 100%; }
.gap-note { margin: 0; text-align: center; font-size: 11px; color: #8795a0; }
.limit-formula math { font-size: 16px; }
.ks-summary { grid-column: 1 / -1; color: #627888; font-size: 12px; margin: 10px 0 0; }
.diagnostics { grid-column: 1 / -1; display: grid; grid-template-columns: 1fr 1fr; gap: 25px; border-top: 1px solid #edf0f3; margin-top: 12px; padding-top: 14px; }
.diagnostics section { min-width: 0; }
.diagnostics h3 { font-size: 15px; font-weight: 600; margin: 0 0 5px; }
.diagnostics p { font-size: 11px; color: #8795a0; margin: 0 0 5px; }
.mechanism { grid-column: 1 / -1; background: #f2f6f8; color: #627888; font-size: 12px; line-height: 1.8; padding: 10px 14px; margin: 10px 0 0; border-radius: 4px; }
@media(max-width: 850px) { .demo { margin: 20px auto; padding: 0 14px; } .frame { grid-template-columns: 1fr; padding: 20px 12px; } .formulas { border-left: 0; border-top: 1px solid #e7ecf0; padding: 15px 0; margin-top: 15px; } .controls { flex-wrap: wrap; } .controls .shiny-input-container { flex-basis: 100%; margin: 0 8px; } }
@media(max-width: 560px) { .diagnostics { grid-template-columns: 1fr; } }
